import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    n = data[idx]
    idx += 1

    dice = []
    for _ in range(n):
        k = data[idx]
        idx += 1
        freq = {}
        for _ in range(k):
            a = data[idx]
            idx += 1
            freq[a] = freq.get(a, 0) + 1
        dice.append((k, freq))

    ans = 0.0

    for i in range(n):
        ki, fi = dice[i]
        for j in range(i + 1, n):
            kj, fj = dice[j]

            if len(fi) <= len(fj):
                small, large = fi, fj
            else:
                small, large = fj, fi

            same = 0
            for value, count in small.items():
                same += count * large.get(value, 0)

            ans = max(ans, same / (ki * kj))

    print(f"{ans:.15f}")

if __name__ == "__main__":
    main()
